head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[wframe > P > scopeInherit]<br/>중첩된 Frame 구조일때 하위 Frame 에서 참조할 수 있는 상위 WFrame 의 범위를 설정합니다.",
    "validation" : [        
        "하위 Frame 에서 스크립트 실행 시 $p.main() 메소드의 Scope 반환 범위와 컴포넌트 참조 범위를 결정합니다.",
        "미설정 또는 none 설정 시 하위 Frame 에서 현재 WFrame 을 $p.main() 메소드로 접근할 수 없고, 컴포넌트도 직접 참조할 수 없습니다.",
        "all 설정 시 하위 Frame 에서 현재 WFrame 을 $p.main() 메소드로 접근할 수 있고, 컴포넌트도 직접 참조할 수 있습니다.",
        "api 설정 시 하위 Frame 에서 현재 WFrame 을 $p.main() 메소드로 접근할 수 있지만, 컴포넌트는 직접 참조할 수 없습니다.", 
        "component 설정 시 하위 Frame 에서 현재 WFrame 을 $p.main() 메소드로 접근할 수 없지만, 컴포넌트는 직접 참조할 수 있습니다.",  
        "recursive 설정 시 하위 Frame 에서 현재 WFrame 을 $p.main() 메소드로 접근할 수 없지만, 컴포넌트는 직접 참조할 수 있습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정   
    let properties = {
        src: "/sample/common_link/wframe_scopeInherit_sub1.xml",
        scopeInherit: con_scopeInherit.getText(),        
    };

    let cList = $c.gcm.createCList(properties);    

    let grp_comp = $c.gcm.getTestGroup();    
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    $c.gcm.createLabel('label="wf1의 input 은 scopeInherit 설정값에 따라 접근 여부가 다르고 wf2의 input은 설정값에 상관없이 접근 불가"', '', 'label1');

    strTarget += '<w2:wframe ' + strNameSpace + ' ' + cList + ' style="height:300px; background-color:silver;" id=""></w2:wframe>';

    // target 생성
    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "wframe",
        strTarget,
        grp_comp
    );
}
